            <td><button (click)="edit(m)">Edit</button></td>
            <td><button (click)="remove(m)">Delete</button></td>
          </tr>
        }
      </tbody>
    </table>
    @if (editing()) {
      <div class="glass" (click)="close()"></div>
      <div class="popup" id="gwt-debug-manufacturer-editor">
        <div><span>Name:</span> <input id="gwt-debug-manufacturer-input" [(ngModel)]="name"></div>
        <div>
          <button id="gwt-debug-manufacturer-save" (click)="save()">Save</button>
          <button id="gwt-debug-manufacturer-close" (click)="close()">Close</button>
        </div>
      </div>
    }
  `,
})
export class ManufacturerComponent implements OnInit {
  private api = inject(ApiService);
  private msg = inject(MessageService);
  items = signal<Manufacturer[]>([]);
  editing = signal<Manufacturer | null>(null);
  isNew = false;
  name = '';

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({
      next: (l) => this.items.set(l),
      error: () => this.msg.error('Failed to load manufacturers'),
    });
  }
  create(): void { this.isNew = true; this.name = ''; this.editing.set({ name: '' }); }
  edit(m: Manufacturer): void { this.isNew = false; this.name = m.name; this.editing.set(m); }
  close(): void { this.editing.set(null); }
  save(): void {
    const target = this.editing();
    if (!target) return;
    const dto: Manufacturer = { ...target, name: this.name };
    this.api.saveManufacturer(dto).subscribe({
      next: (saved) => {
        this.items.update((l) => (this.isNew ? [...l, saved] : l.map((x) => (x.id === saved.id ? saved : x))));
        this.msg.success('Manufacturer saved');
        this.close();
      },
      error: () => this.msg.error('Failed to save manufacturer'),
    });
  }
  remove(m: Manufacturer): void {
    if (!window.confirm('Are you sure you want to delete ' + m.name + '?')) return;
    this.api.deleteManufacturer(m.id!).subscribe({
      next: () => this.items.update((l) => l.filter((x) => x.id !== m.id)),
      error: () => this.msg.error('Failed to delete manufacturer'),
    });
  }
}
